  wire        _committed_T_3 = state == 3'h3;
  wire        io_result_valid_0 = _committed_T_3 & ~io_flush;
  wire        io_readRequest_valid_0 = state == 3'h1 & ~io_flush;
  wire        _state_T = state == 3'h2;
  wire        _state_T_1 = state == 3'h5;
  wire        io_readResponse_ready_0 = _state_T | _state_T_1;
