      | io_request_bits_operation == 5'h4 | io_request_bits_operation == 5'h8
      | io_request_bits_operation == 5'hC | io_request_bits_operation == 5'h10
      | io_request_bits_operation == 5'h14 | io_request_bits_operation == 5'h18
      | io_request_bits_operation == 5'h1C) | (|(io_request_bits_physicalAddress[1:0]));
