      request_operation <= io_request_bits_operation;
      request_physicalAddress <= io_request_bits_physicalAddress;
      request_operand <= io_request_bits_operand;
      result_robid <= io_request_bits_robid;
      result_physicalAddress <= io_request_bits_physicalAddress;
      result_virtualAddress <= io_request_bits_virtualAddress;
