  assign io_request_ready = io_request_ready_0;
  assign io_result_valid = io_result_valid_0;
  assign io_result_bits_robid = result_robid;
  assign io_result_bits_data = result_data;
  assign io_result_bits_storeData = result_storeData;
  assign io_result_bits_storeMask = result_storeMask;
  assign io_result_bits_accessFault = result_accessFault;
  assign io_result_bits_physicalAddress = result_physicalAddress;
  assign io_result_bits_virtualAddress = result_virtualAddress;
  assign io_readRequest_valid = io_readRequest_valid_0;
  assign io_readRequest_bits = request_physicalAddress;
  assign io_readResponse_ready = io_readResponse_ready_0;
