module PhysicalMemoryAttributes(
  input  [31:0] io_iPaddr,
                io_dPaddr,
  output [1:0]  io_iMat,
                io_dMat
);

  assign io_iMat = {1'h0, ~(io_iPaddr[31:16] == 16'h200 | io_iPaddr[31:20] == 12'h1FE)};
  assign io_dMat =
    {1'h0,
     ~(io_dPaddr[31:16] == 16'h200 | io_dPaddr[31:20] == 12'h1FE
       | io_dPaddr[31:30] == 2'h2)};
endmodule

module PmaMmu(
  input         clock,
                reset,
  input  [1:0]  io_privilege,
                io_dataPrivilege,
  input  [31:0] io_satp,
                io_status,
  input         io_flush,
                io_instructionCancel,
                io_fence,
                io_iReq,
  input  [31:0] io_iVaddr,
  input         io_iAccept,
  output        io_iReady,
  output [31:0] io_iPaddr,
  output [1:0]  io_iMat,
  output [9:0]  io_iFaults,
  input         io_dReq,
  input  [31:0] io_dVaddr,
  input         io_dIsStore,
                io_dAccept,
  output        io_dReady,
  output [31:0] io_dPaddr,
  output [1:0]  io_dMat,
  output        io_dAccessFault,
                io_dPageFault,
  input         io_pageRequest_ready,
  output        io_pageRequest_valid,
  output [33:0] io_pageRequest_bits,
  output        io_pageResponse_ready,
  input         io_pageResponse_valid,
  input  [31:0] io_pageResponse_bits_data,
  input         io_pageResponse_bits_error
);

  wire [1:0]  _attributes_io_iMat;
  wire [1:0]  _attributes_io_dMat;
  wire        _tlb_io_request_ready;
  wire        _tlb_io_response_valid;
  wire [33:0] _tlb_io_response_bits_physicalAddress;
  wire        _tlb_io_response_bits_pageFault;
  wire        _tlb_io_response_bits_accessFault;
  wire        iTranslate = io_satp[31] & io_privilege != 2'h3;
  wire        dTranslate = io_satp[31] & io_dataPrivilege != 2'h3;
  wire        iTlbReq =
    io_iReq & iTranslate & ~(|(io_iVaddr[1:0])) & ~io_instructionCancel;
  wire        dTlbReq = io_dReq & dTranslate;
  reg         ownerValid;
  reg         ownerData;
  reg         preferData;
  wire        chooseData = dTlbReq & (~iTlbReq | preferData);
  reg         dataPreempt_REG;
  wire        dataPreempt = dataPreempt_REG & ownerValid & ~ownerData;
  wire        _tlb_io_request_valid_T_2 = ~ownerValid & (iTlbReq | dTlbReq);
  wire        _tlb_io_response_ready_T_1 =
    ownerValid & (ownerData ? io_dAccept : io_iAccept);
  wire        iResponse = ownerValid & ~ownerData & _tlb_io_response_valid;
  wire        dResponse = ownerValid & ownerData & _tlb_io_response_valid;
  wire [33:0] ipa =
    iTranslate ? _tlb_io_response_bits_physicalAddress : {2'h0, io_iVaddr};
  wire [33:0] dpa =
    dTranslate ? _tlb_io_response_bits_physicalAddress : {2'h0, io_dVaddr};
  wire        _iAccessError_T = iTranslate & iResponse;
  wire        io_iReady_0 =
    io_iReq & ((|(io_iVaddr[1:0])) | ~iTranslate | iResponse) & ~io_flush & ~io_fence;
  wire [7:0]  _io_iFaults_T_2 =
    (|(io_iVaddr[1:0]))
      ? 8'h1
      : _iAccessError_T & _tlb_io_response_bits_pageFault
          ? 8'h80
          : {1'h0,
             _iAccessError_T & _tlb_io_response_bits_accessFault | (|(ipa[33:32]))
               | ~(ipa[31] | ipa[31:30] == 2'h0
                   & ~(ipa[31:16] == 16'h200 | ipa[31:20] == 12'h1FE)),
             6'h0};
  wire        io_dReady_0 = io_dReq & (~dTranslate | dResponse) & ~io_flush & ~io_fence;
  wire        _io_dAccessFault_T_1 = dTranslate & dResponse;
  wire        io_dPageFault_0 = _io_dAccessFault_T_1 & _tlb_io_response_bits_pageFault;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (io_iReady_0 & {_io_iFaults_T_2[7:6], _io_iFaults_T_2[0]} == 3'h0 & ~reset
          & _attributes_io_iMat != 2'h1) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: Executable physical regions must be cacheable in the integrated Core\n    at PmaMmu.scala:164 assert(io.iMat === PhysicalMemoryAttributes.MatCacheable,\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (io_dReady_0 & ~reset
          & _attributes_io_dMat != {1'h0,
                                    ~(dpa[31:16] == 16'h200 | dpa[31:20] == 12'h1FE
                                      | dpa[31:30] == 2'h2)}) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: data MAT must match the translated physical address\n    at PmaMmu.scala:168 assert(io.dMat === PhysicalMemoryAttributes.dataMat(io.dPaddr),\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire        _GEN = _tlb_io_request_ready & _tlb_io_request_valid_T_2;
  always @(posedge clock) begin
    if (reset) begin
      ownerValid <= 1'h0;
      ownerData <= 1'h0;
      preferData <= 1'h0;
      dataPreempt_REG <= 1'h0;
    end
    else begin
      ownerValid <=
        ~(_tlb_io_response_ready_T_1 & _tlb_io_response_valid | io_flush | io_fence
          | dataPreempt | ownerValid & ~ownerData & io_instructionCancel)
        & (_GEN | ownerValid);
      if (_GEN) begin
        ownerData <= chooseData;
        preferData <= ~chooseData;
      end
      dataPreempt_REG <=
        ownerValid & ~ownerData & _tlb_io_response_valid & ~io_iAccept & dTlbReq;
    end
  end // always @(posedge)
  Sv32 tlb (
    .clock                            (clock),
    .reset                            (reset),
    .io_request_ready                 (_tlb_io_request_ready),
    .io_request_valid                 (_tlb_io_request_valid_T_2),
    .io_request_bits_virtualAddress   (chooseData ? io_dVaddr : io_iVaddr),
    .io_request_bits_access           (chooseData ? (io_dIsStore ? 2'h2 : 2'h1) : 2'h0),
    .io_request_bits_privilege        (chooseData ? io_dataPrivilege : io_privilege),
    .io_request_bits_satp             (io_satp),
    .io_request_bits_sum              (io_status[18]),
    .io_request_bits_mxr              (io_status[19]),
    .io_response_ready                (_tlb_io_response_ready_T_1),
    .io_response_valid                (_tlb_io_response_valid),
    .io_response_bits_physicalAddress (_tlb_io_response_bits_physicalAddress),
    .io_response_bits_pageFault       (_tlb_io_response_bits_pageFault),
    .io_response_bits_accessFault     (_tlb_io_response_bits_accessFault),
    .io_invalidate                    (io_fence),
    .io_cancel
      (io_flush | ownerValid & ~ownerData & io_instructionCancel | dataPreempt),
    .io_memoryRequest_ready           (io_pageRequest_ready),
    .io_memoryRequest_valid           (io_pageRequest_valid),
    .io_memoryRequest_bits            (io_pageRequest_bits),
    .io_memoryResponse_ready          (io_pageResponse_ready),
    .io_memoryResponse_valid          (io_pageResponse_valid),
    .io_memoryResponse_bits_data      (io_pageResponse_bits_data),
    .io_memoryResponse_bits_error     (io_pageResponse_bits_error)
  );
  PhysicalMemoryAttributes attributes (
    .io_iPaddr (ipa[31:0]),
    .io_dPaddr (dpa[31:0]),
    .io_iMat   (_attributes_io_iMat),
    .io_dMat   (_attributes_io_dMat)
  );
  assign io_iReady = io_iReady_0;
  assign io_iPaddr = ipa[31:0];
  assign io_iMat = _attributes_io_iMat;
  assign io_iFaults = {2'h0, _io_iFaults_T_2};
  assign io_dReady = io_dReady_0;
  assign io_dPaddr = dpa[31:0];
  assign io_dMat = _attributes_io_dMat;
  assign io_dAccessFault =
    ~io_dPageFault_0
    & (_io_dAccessFault_T_1 & _tlb_io_response_bits_accessFault | (|(dpa[33:32]))
       | ~(dpa[31] | dpa[31:30] == 2'h0 & ~(dpa[31:16] == 16'h200 | dpa[31:20] == 12'h1FE)
           | dpa[31:16] == 16'h200 | dpa[31:20] == 12'h1FE));
  assign io_dPageFault = io_dPageFault_0;
endmodule

