  reg [21:0] Memory[0:127];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 22'bx;
  assign R1_data = R1_en ? Memory[R1_addr] : 22'bx;
endmodule

