module Ctrl(
  input         clock,
                reset,
                io_cmtFlushReq,
  input  [31:0] io_cmtFlushPc,
  input         io_cmtPreserveFrontend,
  output        io_flush,
                io_frontendFlush,
  output [31:0] io_flushPc
);

  reg        flushReg;
  reg [31:0] flushPcReg;
  reg        preserveFrontendReg;
  always @(posedge clock) begin
    if (reset) begin
      flushReg <= 1'h0;
      flushPcReg <= 32'h0;
      preserveFrontendReg <= 1'h0;
    end
    else begin
      flushReg <= io_cmtFlushReq;
      flushPcReg <= io_cmtFlushPc;
      preserveFrontendReg <= io_cmtFlushReq & io_cmtPreserveFrontend;
    end
  end // always @(posedge)
  assign io_flush = flushReg;
  assign io_frontendFlush = flushReg & ~preserveFrontendReg;
  assign io_flushPc = flushPcReg;
endmodule

module Decoder(
  input  [31:0] io_inst,
  input  [1:0]  io_privilege,
  input  [31:0] io_status,
