  wire        isOpImm = io_inst[6:0] == 7'h13;
  wire        isOp = io_inst[6:0] == 7'h33;
  wire        isMOp = io_inst[6:0] == 7'h33 & io_inst[31:25] == 7'h1;
  wire        instLui = io_inst[6:0] == 7'h37;
  wire        instAuipc = io_inst[6:0] == 7'h17;
  wire        _instFence_T = io_inst[14:12] == 3'h0;
  wire        instAddi = isOpImm & _instFence_T;
  wire        _instSw_T = io_inst[14:12] == 3'h2;
  wire        instSlti = isOpImm & _instSw_T;
  wire        _instMulhu_T = io_inst[14:12] == 3'h3;
  wire        instSltiu = isOpImm & _instMulhu_T;
  wire        _instLbu_T = io_inst[14:12] == 3'h4;
  wire        instXori = isOpImm & _instLbu_T;
  wire        _instBltu_T = io_inst[14:12] == 3'h6;
  wire        instOri = isOpImm & _instBltu_T;
  wire        instAndi = isOpImm & (&(io_inst[14:12]));
  wire        _instFenceI_T = io_inst[14:12] == 3'h1;
  wire        _instAnd_T_2 = io_inst[31:25] == 7'h0;
  wire        instSlli = isOpImm & _instFenceI_T & _instAnd_T_2;
  wire        _instLhu_T = io_inst[14:12] == 3'h5;
  wire        instSrli = isOpImm & _instLhu_T & _instAnd_T_2;
  wire        _instSra_T_2 = io_inst[31:25] == 7'h20;
  wire        instSrai = isOpImm & _instLhu_T & _instSra_T_2;
  wire        instAdd = isOp & _instFence_T & _instAnd_T_2;
