module EarlyBranchRecovery(
  input         clock,
                reset,
                io_globalFlush,
                io_block,
  input  [4:0]  io_headRobid,
  input         io_laneValid_0,
                io_laneValid_1,
                io_laneIsCond_0,
                io_laneIsCond_1,
  input  [4:0]  io_laneRobid_0,
                io_laneRobid_1,
  input  [31:0] io_lanePc_0,
                io_lanePc_1,
  input         io_lanePredTaken_0,
                io_lanePredTaken_1,
                io_laneTaken_0,
                io_laneTaken_1,
  input  [31:0] io_laneTarget_0,
                io_laneTarget_1,
  input  [3:0]  io_laneFtqId_0,
                io_laneFtqId_1,
  output        io_redirectValid,
  output [31:0] io_redirectPc,
  output [3:0]  io_redirectFtqId,
  output        io_redirectTaken,
                io_pendingValid,
  output [4:0]  io_pendingRobid,
  output        io_recoveryStall
);

  reg         pendingValidR;
  reg  [4:0]  pendingRobidR;
  reg         redirectValidR;
  reg  [31:0] redirectPcR;
  reg  [3:0]  redirectFtqIdR;
  reg         redirectTakenR;
  wire        io_redirectValid_0 = redirectValidR & ~io_globalFlush;
  `ifndef SYNTHESIS
    wire _GEN = io_redirectValid_0 & ~reset;
    always @(posedge clock) begin
      if (_GEN & ~pendingValidR) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: early branch redirect must retain a pending owner\n    at EarlyBranchRecovery.scala:91 assert(io.pendingValid, \"early branch redirect must retain a pending owner\")\n");
        if (`STOP_COND_)
          $fatal;
      end
      if (_GEN & ~(~redirectTakenR | redirectPcR[1:0] == 2'h0)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: misaligned branch target must remain a commit-time exception\n    at EarlyBranchRecovery.scala:92 assert(!io.redirectTaken || !io.redirectPc(1, 0).orR,\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire        eligible_0 =
    io_laneValid_0 & io_laneIsCond_0 & io_laneTaken_0 != io_lanePredTaken_0
    & (~io_laneTaken_0 | io_laneTarget_0[1:0] == 2'h0);
  wire [4:0]  _GEN_0 = {io_headRobid[3:0], io_headRobid[4]};
  wire [4:0]  _age_0_T = {io_laneRobid_0[3:0], io_laneRobid_0[4]} - _GEN_0;
  wire        eligible_1 =
    io_laneValid_1 & io_laneIsCond_1 & io_laneTaken_1 != io_lanePredTaken_1
    & (~io_laneTaken_1 | io_laneTarget_1[1:0] == 2'h0);
  wire [4:0]  _age_1_T = {io_laneRobid_1[3:0], io_laneRobid_1[4]} - _GEN_0;
  wire        selectLane1 = eligible_1 & (~eligible_0 | _age_1_T < _age_0_T);
  wire        accept =
    (|{eligible_1, eligible_0}) & ~io_block
    & (~pendingValidR
       | (selectLane1 ? _age_1_T : _age_0_T) < {pendingRobidR[3:0], pendingRobidR[4]}
       - _GEN_0);
  wire        _GEN_1 = reset | io_globalFlush;
  wire        selectedTaken = selectLane1 ? io_laneTaken_1 : io_laneTaken_0;
  always @(posedge clock) begin
    if (reset) begin
      pendingValidR <= 1'h0;
      redirectValidR <= 1'h0;
    end
    else begin
      pendingValidR <= ~_GEN_1 & (accept | pendingValidR);
      redirectValidR <= ~_GEN_1 & accept;
    end
    if (_GEN_1 | ~accept) begin
    end
    else begin
      pendingRobidR <= selectLane1 ? io_laneRobid_1 : io_laneRobid_0;
      redirectPcR <=
        selectedTaken
          ? (selectLane1 ? io_laneTarget_1 : io_laneTarget_0)
          : (selectLane1 ? io_lanePc_1 : io_lanePc_0) + 32'h4;
      redirectFtqIdR <= selectLane1 ? io_laneFtqId_1 : io_laneFtqId_0;
      redirectTakenR <= selectedTaken;
    end
