  assign io_redirectValid = io_redirectValid_0;
  assign io_redirectPc = redirectPcR;
  assign io_redirectFtqId = redirectFtqIdR;
  assign io_redirectTaken = redirectTakenR;
  assign io_pendingValid = pendingValidR;
  assign io_pendingRobid = pendingRobidR;
  assign io_recoveryStall = pendingValidR | redirectValidR;
endmodule

module Mul(
